for(const report of [false,true])check(report?'settlement report read locks source history against a real concurrent hidden-bank payment':'payment balance read locks source history so a concurrent hidden-bank payment cannot leak into its aggregate',async f=>{
 const h=await paymentFixture(f);assert.equal((await f.request(h.paymentPath,h.paymentInput)).response.status,201);const outside=await f.made('finance/accounts',{code:'PAY-HIDDEN',name:'Synthetic hidden bank',kind:'asset',operationalRole:'bank',hubId:f.otherHub,currencyId:f.currency.id,currencyVersion:1,reason:'Synthetic distinct funding scope'}),runtime=f.pg.runtime!,connect=runtime.connect.bind(runtime);let release!:()=>void,reached!:()=>void;const gate=new Promise<void>(r=>{release=r;}),atHistory=new Promise<void>(r=>{reached=r;});let held=false;
 runtime.connect=async()=>{const c=await connect(),query=c.query.bind(c);c.query=async<Row=Record<string,unknown>>(sql:string,args?:unknown[])=>{const result=await query<Row>(sql,args);if(!held&&sql.startsWith('SELECT NOT EXISTS(SELECT 1 FROM public.payrun_payments p JOIN public.finance_accounts')){held=true;reached();await gate;}return result;};return c;};
 const path=report?'payroll/net-postings/'+h.posting.id+'/settlement-report':h.statusPath;
 let reader:ReturnType<typeof f.request>|undefined,writer:ReturnType<typeof f.request>|undefined;try{reader=f.request(path,undefined,'staff');await atHistory;writer=f.request(h.paymentPath,{...h.paymentInput,amount:'500.00',reference:'HIDDEN-FUND',fundingAccount:{id:outside.id,version:1}});let waiting=false;for(let k=0;k<100;k++){waiting=(await f.pg.query<{n:number}>("SELECT count(*)::integer n FROM pg_stat_activity WHERE datname=current_database() AND wait_event_type='Lock' AND wait_event='advisory'")).rows[0].n>0;if(waiting)break;await new Promise(r=>setTimeout(r,2));}assert.equal(waiting,true,'concurrent writer must actually wait behind the balance-read worker lock');release();const [read,write]=await Promise.all([reader,writer]);assert.equal(read.response.status,200,JSON.stringify(read.body));assert.equal((report?read.body.data.settlement:read.body.data).paid,'1000.00');if(report)assert.equal(read.body.data.events.length,1);assert.equal(write.response.status,201,JSON.stringify(write.body));assert.equal((await f.request(path,undefined,'staff')).response.status,404);const current=(await f.request(path)).body.data;assert.equal((report?current.settlement:current).paid,'1500.00');}finally{release();await Promise.allSettled([reader,writer].filter(Boolean));runtime.connect=connect;}
},true);
